    lines = [json.loads(l) for l in f.readlines()]

# Look for exact correctness messages used by ARC
print("Searching for exact correctness phrases...")
correctness_phrases = ['Correct!', 'Incorrect!', 'Wrong answer', 'Answer is correct', 'Your answer is wrong']

for line in lines:
    msg = line.get('message', {})
    content = msg.get('content', [])

    if isinstance(content, list):
        for item in content:
            if item.get('type') == 'text':
                text = item.get('text', '')
                for phrase in correctness_phrases:
                    if phrase.lower() in text.lower():
                        print(f"\n=== FOUND {phrase} ===")
                        print(text[:300])

